<script setup lang="ts">
import { displaySettings } from '../data/display-settings';
import { onMounted, onBeforeUnmount, reactive, ref, watch } from 'vue';
import { captureScheduleSource, loadSchedule, saveSchedule, runSchedule, scheduleState, snapshotStorage, storageError, refreshSnapshotStorage } from '../data/snapshot-schedule';
import {askSnapshotOptions} from '../data/unlock-backup';
const controller=new AbortController();onBeforeUnmount(()=>controller.abort());
import {formatExhaustion as spaceDate} from '../../../../preview-data/storage-display.mjs';
import { formatSize } from '../config/file-size.mjs';
import { storedSnapshots, refreshSnapshots } from '../data/stored-snapshots';
import HelpTip from './HelpTip.vue';
import {inventoryDatasets} from '../data/inventory'; const inventory=inventoryDatasets['publication-snapshot.json'];
import { useFormGuard } from '../data/form-guard';
watch([storedSnapshots,scheduleState], () => { void refreshSnapshotStorage(); });
const cleanup = ref<any>(null);const cleanupForm=reactive({interval:1,unit:'days',retention:30,retentionUnit:'days'});
async function loadCleanup(){const response=await fetch('/api/snapshot-cleanup');if(!response.ok)throw new Error('Cleanup scheduling is unavailable.');cleanup.value=await response.json();Object.assign(cleanupForm,{interval:cleanup.value.interval,unit:cleanup.value.unit,retention:cleanup.value.retention,retentionUnit:cleanup.value.retentionUnit});}
async function saveCleanup(enabled=cleanup.value?.enabled||false){busy.value=true;message.value='';try{const response=await fetch('/api/snapshot-cleanup',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({...cleanupForm,enabled})});if(!response.ok)throw new Error('Check cleanup interval and retention.');cleanup.value=await response.json();message.value='Cleanup Schedule Saved.';guard.clean();}catch(e){message.value=e instanceof Error?e.message:'Save failed.';}finally{busy.value=false;}}
async function runCleanup(){busy.value=true;try{const response=await fetch('/api/snapshot-cleanup/run',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});if(!response.ok)throw new Error('Cleanup failed.');cleanup.value=await response.json();await refreshSnapshots();await refreshSnapshotStorage();message.value=`Cleanup Completed: ${cleanup.value.lastDeleted} Snapshots Removed.`;}catch(e){message.value=e instanceof Error?e.message:'Cleanup failed.';}finally{busy.value=false;}}
const form = reactive({ interval: 1, unit: 'days', namespace: '' });
const busy = ref(false); const message = ref(''); const loaded = ref(false);
onMounted(async () => { try { const state = await loadSchedule(); Object.assign(form, { interval: state.interval, unit: state.unit, namespace: state.scope?.namespace || '' }); await loadCleanup(); await refreshSnapshotStorage(); loaded.value = true; guard.clean(); } catch (error) { message.value = error instanceof Error ? error.message : 'Schedule unavailable.'; } });
async function save(enabled = scheduleState.value?.enabled || false) {
  busy.value = true; message.value = '';
  try { await saveSchedule({ ...form, enabled, current: captureScheduleSource(form.namespace) }); message.value = enabled ? 'Automatic snapshots enabled. Settings saved on the hosting server.' : 'Settings saved. Automatic snapshots disabled.'; guard.clean(); } catch (error) { message.value = error instanceof Error ? error.message : 'Save failed.'; } finally { busy.value = false; }
}
async function run() { busy.value = true; message.value = ''; try { let options=await askSnapshotOptions(false,controller.signal);try{await runSchedule(form.namespace,options.password,options.includeSecrets);}finally{options.password='';} await refreshSnapshots(); message.value = 'Snapshot ZIP Saved.'; } catch (error) { message.value = error instanceof Error ? error.message : 'Capture failed.'; } finally { busy.value = false; } }
const guard = useFormGuard('history', () => 'Snapshot Schedule', () => ({form:{...form},cleanup:{...cleanupForm}}), state => {Object.assign(form,state.form);Object.assign(cleanupForm,state.cleanup);}, () => loaded.value);
</script>
<template>
  <div class="schedule-panels"><section class="snapshot-schedule"><div class="schedule-heading"><h3>Automatic Snapshot Schedule <HelpTip label="Automatic Snapshot Schedule Help" text="The hosting service runs the saved scope even with the browser closed. The preview uses saved inspection data, not fresh cluster observations. Automatic runs exclude Secret values; Run Now asks whether to include and encrypt Secrets. ZIPs contain a recovery index and manifests. Save Schedule persists settings; Enable starts scheduling."/></h3><span class="schedule-badge" :class="scheduleState ? scheduleState.enabled ? 'enabled' : 'disabled' : 'unknown'">{{scheduleState ? scheduleState.enabled ? 'Enabled' : 'Disabled' : 'Unavailable'}}</span></div><div class="schedule-fields"><label class="schedule-number">Every<input v-model.number="form.interval" type="number" min="1" max="365"></label><label class="schedule-unit">Unit<select v-model="form.unit"><option value="minutes">Minutes</option><option value="hours">Hours</option><option value="days">Days</option><option value="weeks">Weeks</option><option value="months">Months</option></select></label><label class="schedule-scope">Scope<select v-model="form.namespace"><option value="">All Known Routing Configuration</option><option v-for="namespace in inventory.namespaces" :key="namespace">{{ namespace }}</option></select></label><div class="schedule-actions"><button type="button" :disabled="busy || !loaded" @click="save()">Save Schedule</button><button type="button" :disabled="busy || !loaded" @click="save(!scheduleState?.enabled)">{{ scheduleState?.enabled ? 'Disable' : 'Enable' }}</button><button type="button" :disabled="busy || !loaded" @click="run">Run Now</button></div></div><p>Next Snapshot: {{ scheduleState?.nextRun ? new Date(scheduleState.nextRun).toLocaleString() : 'Not Scheduled' }}</p></section><section class="snapshot-schedule"><div class="schedule-heading"><h3>Automatic Snapshot Cleanup <HelpTip label="Automatic Snapshot Cleanup Help" text="Cleanup removes backups older than retention while preserving the newest backup of each known scope and configuration item. Save Schedule persists retention settings; Enable starts periodic cleanup; Run Now performs cleanup immediately."/></h3><span class="schedule-badge" :class="cleanup ? cleanup.enabled ? 'enabled' : 'disabled' : 'unknown'">{{cleanup ? cleanup.enabled ? 'Enabled' : 'Disabled' : 'Unavailable'}}</span></div><div class="schedule-fields"><label class="schedule-number">Every<input v-model.number="cleanupForm.interval" type="number" min="1" max="365"></label><label class="schedule-unit">Unit<select v-model="cleanupForm.unit"><option value="minutes">Minutes</option><option value="hours">Hours</option><option value="days">Days</option><option value="weeks">Weeks</option><option value="months">Months</option></select></label><label class="schedule-number">Keep For<input v-model.number="cleanupForm.retention" type="number" min="1" max="365"></label><label class="schedule-unit">Retention Unit<select v-model="cleanupForm.retentionUnit"><option value="minutes">Minutes</option><option value="hours">Hours</option><option value="days">Days</option><option value="weeks">Weeks</option><option value="months">Months</option></select></label><div class="schedule-actions"><button type="button" :disabled="busy||!loaded" @click="saveCleanup()">Save Schedule</button><button type="button" :disabled="busy||!loaded" @click="saveCleanup(!cleanup?.enabled)">{{ cleanup?.enabled ? 'Disable' : 'Enable' }}</button><button type="button" :disabled="busy||!loaded" @click="runCleanup">Run Now</button></div></div><p>Next Delete: {{ cleanup?.nextRun ? new Date(cleanup.nextRun).toLocaleString() : 'Not Scheduled' }}</p></section><section class="snapshot-storage-row" aria-label="Snapshot Storage"><h3>Snapshot Storage <HelpTip label="Snapshot Storage Help" text="Available / total capacity comes from the actual mounted filesystem containing the snapshot directory, bounded by configured quotas. Remaining count and run-out date use the largest complete backup and saved schedule, before cleanup or competing usage. Unknown limits are unavailable. Estimates beyond one calendar year display infinity. Cleanup and competing disk usage can change the prediction."/></h3><div class="storage-three"><div><strong>Available Drive Space</strong><span>{{snapshotStorage?`${formatSize(snapshotStorage.availableBytes)} / ${formatSize(snapshotStorage.totalBytes)}`:'Unavailable'}}</span></div><div><strong>Largest Snapshot</strong><span>{{snapshotStorage?formatSize(snapshotStorage.largestSnapshotBytes):'Unavailable'}}</span><small v-if="snapshotStorage?.capacity!==null && snapshotStorage">Approximately {{snapshotStorage.capacity.toLocaleString()}} More Snapshots Fit</small></div><div><strong>Estimated Run Out Of Space</strong><span :title="snapshotStorage?.runOutAt||snapshotStorage?.reason">{{spaceDate(snapshotStorage)}}</span></div></div></section><p v-if="message||scheduleState?.lastError||cleanup?.lastError||storageError" class="schedule-errors" role="status">{{message||scheduleState?.lastError||cleanup?.lastError||storageError}}</p></div>
</template>
<style scoped>
.storage-summary{margin-top:12px;padding-top:10px;border-top:1px solid var(--border,#384352)}.storage-summary p{margin-top:5px}.estimate-note{font-size:10px}.snapshot-schedule { flex-shrink:0; border:1px solid var(--border,#384352); border-radius:6px; background:var(--input-bg,#1c2430); padding:16px; margin-top:16px; max-height:45%; overflow:auto; }.schedule-heading { display:flex; align-items:center; justify-content:space-between; gap:12px; }.schedule-heading h3 { margin:0 0 12px; font-size:15px; }.schedule-heading span { font-size:12px; color:#a9d2ff; }.schedule-fields { display:flex; flex-wrap:wrap; gap:14px; align-items:end; }label { display:flex; flex-direction:column; gap:7px; font-size:12px; }input,select { box-sizing:border-box; min-height:38px; padding:8px; background:var(--box-bg,#242c38); color:inherit; border:1px solid var(--border,#384352); border-radius:5px; font:inherit; }input { width:70px; }.schedule-actions { display:flex; gap:10px; }button { padding:10px; border:0; border-radius:5px; background:#326fb4; color:white; cursor:pointer; font:inherit; font-size:12px; }button:disabled { opacity:.5; }p { font-size:11px; line-height:1.5; color:var(--muted,#a5b1c3); margin:8px 0 0; }
</style>

<style scoped>.schedule-panels{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:16px;flex:0 0 auto;max-height:65%;min-height:0;margin-top:16px}.schedule-panels .snapshot-schedule{margin:0;max-height:none;min-height:0;overflow:auto;padding:16px}.schedule-actions{flex-wrap:wrap;margin:0 0 0 auto;justify-content:flex-end}.schedule-fields{gap:12px;justify-content:flex-start}.schedule-fields label{min-width:0;flex:0 0 auto}.schedule-fields .schedule-number{width:70px}.schedule-fields .schedule-unit{width:110px}.schedule-fields .schedule-scope{width:280px;max-width:100%}@media(max-width:1450px){.schedule-fields .schedule-scope{width:200px}.schedule-panels{max-height:65%}}.schedule-fields select{width:100%;min-width:0}.schedule-fields input{width:100%}.schedule-heading{align-items:start}@media(max-width:700px){.schedule-panels{grid-template-columns:1fr}} </style>
<style scoped>.snapshot-storage-row{grid-column:1/-1;background:var(--box-bg);border:1px solid var(--border);border-radius:5px;padding:14px}.snapshot-storage-row>summary{cursor:pointer}.storage-three{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px;margin-top:16px}.storage-three strong,.storage-three span,.storage-three small{display:block}.storage-three strong{font-size:12px;color:var(--muted)}.storage-three span{font-size:18px;margin-top:8px}.storage-three small{font-size:11px;color:var(--muted);margin-top:8px}.schedule-badge{border-radius:4px;padding:4px 8px}.schedule-badge.enabled{color:#9be7b2;background:#153c29}.schedule-badge.disabled{color:#ffb3ad;background:#4c282e}.schedule-badge.unknown{color:var(--muted);background:var(--box-bg)}.schedule-errors{grid-column:1/-1}@media(max-width:700px){.storage-three{grid-template-columns:1fr}}</style>
<style scoped>.snapshot-storage-row{grid-column:1/-1;background:var(--box-bg);border:1px solid var(--border);border-radius:5px;padding:14px}.snapshot-storage-row h3{font-size:14px;margin:0}.storage-three{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px;margin-top:16px}.storage-three strong,.storage-three span,.storage-three small{display:block}.storage-three strong{font-size:12px;color:var(--muted)}.storage-three span{font-size:18px;margin-top:8px}.storage-three small{font-size:11px;color:var(--muted);margin-top:8px}@media(max-width:700px){.storage-three{grid-template-columns:1fr}}</style>
